CREATE TABLE IF NOT EXISTS enterprise_customer_experience (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, tenant_id UUID REFERENCES organizations(id) ON DELETE CASCADE, customer_code TEXT NOT NULL, segment TEXT DEFAULT 'ENTERPRISE', lifecycle_stage TEXT DEFAULT 'ACTIVE', overall_experience_score NUMERIC(5,2) DEFAULT 88.5, retention_status TEXT DEFAULT 'STABLE', provenance_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_context (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, customer_id UUID REFERENCES enterprise_customer_experience(id) ON DELETE CASCADE, tier TEXT DEFAULT 'TIER_1', preferred_channel TEXT DEFAULT 'OMNICHANNEL', sla_tier TEXT DEFAULT 'PLATINUM', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_journeys (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, journey_name TEXT NOT NULL, journey_type TEXT DEFAULT 'ONBOARDING', friction_score NUMERIC(5,2) DEFAULT 14.5, completion_rate_pct NUMERIC(5,2) DEFAULT 94.2, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_journey_stages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, journey_id UUID REFERENCES enterprise_customer_journeys(id) ON DELETE CASCADE, stage_number INTEGER NOT NULL, stage_name TEXT NOT NULL, touchpoint_count INTEGER DEFAULT 3, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_cases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, customer_id UUID REFERENCES enterprise_customer_experience(id) ON DELETE CASCADE, case_number TEXT NOT NULL, category TEXT DEFAULT 'TECHNICAL_SUPPORT', severity TEXT DEFAULT 'HIGH', status TEXT DEFAULT 'RESOLVED', channel TEXT DEFAULT 'PORTAL', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_performance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, first_response_time_minutes NUMERIC(8,2) DEFAULT 12.4, resolution_time_hours NUMERIC(8,2) DEFAULT 4.2, first_contact_resolution_rate_pct NUMERIC(5,2) DEFAULT 82.5, sla_adherence_rate_pct NUMERIC(5,2) DEFAULT 99.1, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_quality (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, case_id UUID REFERENCES enterprise_service_cases(id) ON DELETE CASCADE, quality_score NUMERIC(5,2) DEFAULT 95.0, audit_status TEXT DEFAULT 'VERIFIED_AUDIT', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_defects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, defect_type TEXT NOT NULL, severity TEXT DEFAULT 'MEDIUM', containment_status TEXT DEFAULT 'CONTAINED', occurred_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_complaints (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, customer_id UUID REFERENCES enterprise_customer_experience(id) ON DELETE CASCADE, complaint_type TEXT NOT NULL, regulatory_sensitivity TEXT DEFAULT 'LOW', status TEXT DEFAULT 'RESOLVED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_escalations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, case_id UUID REFERENCES enterprise_service_cases(id) ON DELETE CASCADE, escalation_level TEXT DEFAULT 'TIER_3', reason TEXT NOT NULL, status TEXT DEFAULT 'CLOSED', escalated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_voice_of_customer (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, feedback_source TEXT DEFAULT 'SURVEY', feedback_text TEXT NOT NULL, theme TEXT DEFAULT 'USABILITY', sentiment_score NUMERIC(5,2) DEFAULT 84.0, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_sentiment (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, customer_id UUID REFERENCES enterprise_customer_experience(id) ON DELETE CASCADE, sentiment_category TEXT DEFAULT 'POSITIVE', confidence_score NUMERIC(5,2) DEFAULT 91.5, analyzed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_effort (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, journey_id UUID REFERENCES enterprise_customer_journeys(id) ON DELETE CASCADE, effort_score NUMERIC(5,2) DEFAULT 2.1, transfer_count INTEGER DEFAULT 0, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_knowledge (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, article_title TEXT NOT NULL, category TEXT DEFAULT 'TROUBLESHOOTING', effectiveness_score NUMERIC(5,2) DEFAULT 89.2, view_count INTEGER DEFAULT 1420, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_capacity (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, department_code TEXT DEFAULT 'CUSTOMER_OPS', queue_depth INTEGER DEFAULT 14, agent_utilization_rate NUMERIC(5,2) DEFAULT 78.4, evaluated_at TIMESTAMPTZ DEFAULT NOW());
