CREATE TABLE IF NOT EXISTS enterprise_customer_retention (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, customer_id UUID REFERENCES enterprise_customer_experience(id) ON DELETE CASCADE, retention_probability_pct NUMERIC(5,2) DEFAULT 94.5, strategy TEXT DEFAULT 'PROACTIVE_ENGAGEMENT', assessed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_churn_signals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, customer_id UUID REFERENCES enterprise_customer_experience(id) ON DELETE CASCADE, signal_type TEXT DEFAULT 'USAGE_DROP', severity TEXT DEFAULT 'MEDIUM', confidence_score NUMERIC(5,2) DEFAULT 84.0, detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_recovery (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, complaint_id UUID REFERENCES enterprise_customer_complaints(id) ON DELETE CASCADE, recovery_action TEXT NOT NULL, compensation_amount_usd NUMERIC(10,2) DEFAULT 0.00, status TEXT DEFAULT 'AI_PROPOSED', created_at TIMESTAMPTZ DEFAULT NOW());
