CREATE TABLE IF NOT EXISTS enterprise_service_incidents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, incident_title TEXT NOT NULL, severity TEXT DEFAULT 'SEV_2', duration_minutes NUMERIC(8,2) DEFAULT 35.0, status TEXT DEFAULT 'RESOLVED', occurred_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_root_causes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, incident_id UUID REFERENCES enterprise_service_incidents(id) ON DELETE CASCADE, root_cause_category TEXT DEFAULT 'CONFIG_DRIFT', causal_confidence_score NUMERIC(5,2) DEFAULT 89.0, status TEXT DEFAULT 'VERIFIED', analyzed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_service_automation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, candidate_name TEXT NOT NULL, deflection_potential_pct NUMERIC(5,2) DEFAULT 38.0, status TEXT DEFAULT 'AI_PROPOSED', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_experience_scenarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, scenario_name TEXT NOT NULL, simulated_csat_delta_pct NUMERIC(5,2) DEFAULT 12.0, status TEXT DEFAULT 'SIMULATED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_experience_forecasts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, forecast_horizon TEXT DEFAULT '12_MONTHS', projected_case_volume INTEGER DEFAULT 4500, projected_satisfaction_score NUMERIC(5,2) DEFAULT 91.0, status TEXT DEFAULT 'FORECAST', confidence_score NUMERIC(5,2) DEFAULT 88.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_customer_experience_traces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, root_signal_id TEXT NOT NULL, trace_payload JSONB DEFAULT '{}'::jsonb, provenance_hash TEXT NOT NULL, generated_at TIMESTAMPTZ DEFAULT NOW());
